class TreeAncestor {
    vector<vector<int>> up;
    public:TreeAncestor(int n,vector<int>& parent){
        int log=1;
        while((1<<log)<=n)++log;
        up.assign(log,vector<int>(n));
        up[0]=parent;
        for(int bit=1;bit<log;++bit)for(int node=0;node<n;++node){
            int middle=up[bit-1][node];
            up[bit][node]=middle==-1?-1:up[bit-1][middle];
        }
    }
    int getKthAncestor(int node,int k){
        for(int bit=0;bit<(int)up.size()&&node!=-1;++bit)if(k&(1<<bit))node=up[bit][node];
        return node;
    }
};
